{
  "name": "@inferhub/helper",
  "version": "0.2.9",
  "description": "Point coding agents and IDEs at InferHub \u2014 Claude Code, Codex, OpenCode, Hermes, OpenClaw, and more. Optionally install usage statusline plugins.",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "bin": {
    "inferhub-helper": "dist/cli.js",
    "ih-helper": "dist/cli.js"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "dev": "tsc -p tsconfig.json --watch",
    "test": "node --import tsx --test tests/**/*.test.ts",
    "prepublishOnly": "npm run build",
    "start": "node dist/cli.js"
  },
  "engines": {
    "node": ">=18.0.0"
  },
  "keywords": [
    "inferhub",
    "ai",
    "claude",
    "codex",
    "opencode",
    "hermes",
    "openclaw",
    "openai-compatible",
    "cli"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/inferhub/helper.git"
  },
  "homepage": "https://inferhub.dev",
  "publishConfig": {
    "access": "public"
  },
  "devDependencies": {
    "@types/node": "^22.15.0",
    "tsx": "^4.19.0",
    "typescript": "^5.8.0"
  },
  "dependencies": {
    "@inquirer/prompts": "^7.10.1"
  }
}

#!/usr/bin/env node
import { DEFAULT_BASE_URL, PROVIDER_NAME, } from "./constants.js";
import { applyToAgents, installUsagePlugins, listAdapters, resetAgents, statusAll, } from "./index.js";
import { validateApiKey } from "./validate.js";
import { normalizeBaseUrl } from "./fsutil.js";
import { canRunInteractive, runInteractiveWizard } from "./interactive.js";
const VERSION = "0.2.9";
function printHelp() {
    console.log(`
${PROVIDER_NAME} Helper v${VERSION}
Point coding agents at ${DEFAULT_BASE_URL}

Usage:
  inferhub-helper                  Interactive wizard (default)
  inferhub-helper setup            Same as interactive wizard
  inferhub-helper apply [opts]     Non-interactive apply
  inferhub-helper plugins [opts]   Install usage plugins (statusline / hooks)
  inferhub-helper status           Show agent config status
  inferhub-helper reset [opts]     Remove InferHub settings
  inferhub-helper validate --key K Check key via GET /v1/models
  inferhub-helper list             List supported agents
  inferhub-helper help             This help

Interactive flow:
  1. Enter API key  → validated against /v1/models
  2. Select agents  → multi-select (space to toggle)
  3. Search models  → type to filter, enter to pick
  4. Confirm        → write configs
  5. Usage plugins  → optional Claude/Codex/OpenCode usage statusline

Options:
  --key, -k <key>         InferHub API key (sk-airo-…)
  --base-url <url>        Default: ${DEFAULT_BASE_URL}
  --model, -m <id>        Primary model id from /v1/models
  --subagent-model <id>   Secondary model (Codex/OpenCode subagent)
  --agents <list>         Comma list or "all" / "installed"
  --models <list>         Extra model ids (OpenCode/OpenClaw)
  --plugins [list]        Install usage plugins: claude,opencode (or "all")
  --no-plugins            Skip usage-plugin install in apply/wizard
  --dry-run               Print actions without writing
  --yes, -y               Skip confirmation (non-interactive apply)
  --json                  Machine-readable output

Examples:
  npx @inferhub/helper
  inferhub-helper setup
  inferhub-helper apply -k sk-airo-… -m grok-4.5 --agents claude,codex -y --plugins all
  inferhub-helper plugins --plugins all
  inferhub-helper status
`.trim());
}
function parseArgs(argv) {
    const flags = { _: [] };
    for (let i = 0; i < argv.length; i++) {
        const a = argv[i];
        const next = () => argv[++i];
        switch (a) {
            case "--key":
            case "-k":
                flags.key = next();
                break;
            case "--base-url":
                flags.baseUrl = next();
                break;
            case "--model":
            case "-m":
                flags.model = next();
                break;
            case "--subagent-model":
                flags.subagentModel = next();
                break;
            case "--agents":
                flags.agents = next();
                break;
            case "--models":
                flags.models = next();
                break;
            case "--plugins": {
                const v = next();
                // allow bare --plugins (means all) when next is another flag or missing
                if (!v || v.startsWith("-")) {
                    flags.plugins = "all";
                    if (v && v.startsWith("-"))
                        i--; // re-process flag
                }
                else {
                    flags.plugins = v;
                }
                break;
            }
            case "--no-plugins":
                flags.noPlugins = true;
                break;
            case "--dry-run":
                flags.dryRun = true;
                break;
            case "--yes":
            case "-y":
                flags.yes = true;
                break;
            case "--json":
                flags.json = true;
                break;
            case "--help":
            case "-h":
                flags.help = true;
                break;
            case "--version":
            case "-V":
                flags.version = true;
                break;
            default:
                if (a.startsWith("-")) {
                    console.error(`Unknown flag: ${a}`);
                    process.exitCode = 2;
                }
                else {
                    flags._.push(a);
                }
        }
    }
    return flags;
}
function parseAgentList(raw, fallback) {
    if (!raw || raw === "installed")
        return fallback === "all" ? "all" : "installed";
    if (raw === "all")
        return "all";
    return raw
        .split(",")
        .map((s) => s.trim().toLowerCase())
        .filter(Boolean);
}
async function cmdStatus(flags) {
    const rows = await statusAll();
    if (flags.json) {
        console.log(JSON.stringify(rows, null, 2));
        return;
    }
    console.log(`\n${PROVIDER_NAME} — agent status\n`);
    for (const r of rows) {
        const mark = r.configured ? "✓" : r.installed ? "·" : " ";
        const state = r.configured
            ? "configured"
            : r.installed
                ? "installed"
                : "not found";
        console.log(`  [${mark}] ${r.name.padEnd(16)} ${state.padEnd(12)} ${r.configPath ?? ""}`);
        if (r.message)
            console.log(`      ${r.message}`);
    }
    console.log();
}
async function cmdList(flags) {
    const list = listAdapters().map((a) => ({
        id: a.id,
        name: a.name,
        description: a.description,
    }));
    if (flags.json) {
        console.log(JSON.stringify(list, null, 2));
        return;
    }
    console.log(`\nSupported agents:\n`);
    for (const a of list) {
        console.log(`  ${a.id.padEnd(12)} ${a.name}`);
        console.log(`               ${a.description}`);
    }
    console.log();
}
async function cmdValidate(flags) {
    const key = flags.key ?? process.env.INFERHUB_API_KEY;
    if (!key) {
        console.error("Pass --key or set INFERHUB_API_KEY");
        process.exitCode = 1;
        return;
    }
    const result = await validateApiKey({
        apiKey: key,
        baseUrl: flags.baseUrl,
    });
    if (flags.json) {
        console.log(JSON.stringify(result, null, 2));
        return;
    }
    if (!result.ok) {
        console.error(`✗ ${result.error}`);
        process.exitCode = 1;
        return;
    }
    console.log(`✓ key valid — ${result.models.length} model(s) at ${result.baseUrl}`);
    for (const m of result.models.slice(0, 40)) {
        console.log(`  - ${m.id}${m.ownedBy ? ` (${m.ownedBy})` : ""}`);
    }
    if (result.models.length > 40) {
        console.log(`  … +${result.models.length - 40} more`);
    }
}
/**
 * Non-interactive apply — requires --key + --model (or env key + --model).
 * If required flags are missing and we have a TTY, fall through to wizard.
 */
async function cmdApplyNonInteractive(flags) {
    const key = flags.key ?? process.env.INFERHUB_API_KEY ?? "";
    const baseUrl = normalizeBaseUrl(flags.baseUrl ?? DEFAULT_BASE_URL);
    if (!key || !flags.model) {
        if (canRunInteractive()) {
            await runInteractiveWizard({
                apiKey: key || undefined,
                baseUrl,
                dryRun: flags.dryRun,
            });
            return;
        }
        console.error("Non-interactive apply requires --key and --model (or run in a TTY for the wizard).");
        process.exitCode = 1;
        return;
    }
    process.stdout.write(`Validating key against ${baseUrl}/models … `);
    const validation = await validateApiKey({ apiKey: key, baseUrl });
    if (!validation.ok) {
        console.log("failed");
        console.error(`✗ ${validation.error}`);
        process.exitCode = 1;
        return;
    }
    console.log(`ok (${validation.models.length} models)`);
    const model = flags.model;
    const extraModels = flags.models
        ? flags.models
            .split(",")
            .map((s) => s.trim())
            .filter(Boolean)
        : undefined;
    const agentSel = parseAgentList(flags.agents, "installed");
    const results = await applyToAgents(agentSel, {
        apiKey: key,
        baseUrl,
        model,
        subagentModel: flags.subagentModel,
        models: extraModels,
        dryRun: flags.dryRun,
    });
    let pluginResults = [];
    if (!flags.noPlugins && flags.plugins) {
        pluginResults = await cmdInstallPlugins(flags, { silentJson: true });
    }
    if (flags.json) {
        console.log(JSON.stringify({ model, baseUrl, results, plugins: pluginResults }, null, 2));
        return;
    }
    console.log("");
    for (const r of results) {
        console.log(`  ${r.success ? "✓" : "✗"} ${r.name}: ${r.message}`);
        if (r.configPath)
            console.log(`      ${r.configPath}`);
    }
    if (results.length === 0) {
        console.log("  (no matching agents — install Claude/Codex/… or pass --agents all)");
    }
    if (pluginResults.length) {
        console.log("\n  Usage plugins:");
        for (const p of pluginResults) {
            console.log(`  ${p.success ? "✓" : "✗"} ${p.target}: ${p.message}`);
        }
    }
    console.log("");
}
function parsePluginTargets(raw) {
    if (!raw || raw === "all" || raw === "true" || raw === "1") {
        return ["claude", "opencode"];
    }
    const allowed = new Set(["claude", "opencode"]);
    return raw
        .split(",")
        .map((s) => s.trim().toLowerCase())
        .filter((s) => allowed.has(s));
}
async function cmdInstallPlugins(flags, opts) {
    const targets = parsePluginTargets(flags.plugins ?? "all");
    const results = await installUsagePlugins({
        targets,
        dryRun: flags.dryRun,
    });
    if (flags.json && !opts?.silentJson) {
        console.log(JSON.stringify(results, null, 2));
        return results;
    }
    if (!flags.json) {
        console.log("\nUsage plugins\n");
        for (const r of results) {
            console.log(`  ${r.success ? "✓" : "✗"} ${r.target}: ${r.message}`);
        }
        console.log("\n  Requires GET /v1/me/usage (live). Bins: inferhub-statusline, inferhub-usage\n");
    }
    return results;
}
async function cmdReset(flags) {
    const agentSel = parseAgentList(flags.agents, "all");
    const results = await resetAgents(agentSel === "installed" ? "all" : agentSel, { dryRun: flags.dryRun });
    if (flags.json) {
        console.log(JSON.stringify(results, null, 2));
        return;
    }
    for (const r of results) {
        console.log(`  ${r.success ? "✓" : "✗"} ${r.name}: ${r.message}`);
    }
}
async function main() {
    const flags = parseArgs(process.argv.slice(2));
    if (flags.version) {
        console.log(VERSION);
        return;
    }
    if (flags.help) {
        printHelp();
        return;
    }
    const cmd = flags._[0];
    // Default (no command) → interactive wizard
    if (!cmd || cmd === "setup" || cmd === "wizard" || cmd === "interactive") {
        if (!canRunInteractive() && !flags.yes) {
            console.error("Interactive mode needs a TTY. Use `apply --key … --model … -y` or run in a terminal.");
            process.exitCode = 1;
            return;
        }
        if (!canRunInteractive() && flags.yes) {
            // scripting escape hatch
            await cmdApplyNonInteractive(flags);
            return;
        }
        try {
            await runInteractiveWizard({
                apiKey: flags.key,
                baseUrl: flags.baseUrl,
                dryRun: flags.dryRun,
            });
        }
        catch (err) {
            if (isExitPromptError(err)) {
                console.log("\nCancelled.");
                process.exitCode = 130;
                return;
            }
            throw err;
        }
        return;
    }
    switch (cmd) {
        case "help":
            printHelp();
            break;
        case "status":
            await cmdStatus(flags);
            break;
        case "list":
            await cmdList(flags);
            break;
        case "validate":
            await cmdValidate(flags);
            break;
        case "apply":
            try {
                await cmdApplyNonInteractive(flags);
            }
            catch (err) {
                if (isExitPromptError(err)) {
                    console.log("\nCancelled.");
                    process.exitCode = 130;
                    return;
                }
                throw err;
            }
            break;
        case "plugins":
        case "plugin":
        case "usage-plugins":
            await cmdInstallPlugins({ ...flags, plugins: flags.plugins ?? "all" });
            break;
        case "reset":
            await cmdReset(flags);
            break;
        default:
            console.error(`Unknown command: ${cmd}`);
            printHelp();
            process.exitCode = 2;
    }
}
function isExitPromptError(err) {
    return (!!err &&
        typeof err === "object" &&
        "name" in err &&
        err.name === "ExitPromptError");
}
main().catch((err) => {
    if (isExitPromptError(err)) {
        console.log("\nCancelled.");
        process.exitCode = 130;
        return;
    }
    console.error(err instanceof Error ? err.message : err);
    process.exitCode = 1;
});
