export { DEFAULT_BASE_URL, PROVIDER_ID, PROVIDER_NAME } from "./constants.js";
export { validateApiKey } from "./validate.js";
export { adapters, adapterById, listAdapters, getAdapter, claudeAdapter, codexAdapter, opencodeAdapter, hermesAdapter, openclawAdapter, clineAdapter, } from "./adapters/index.js";
export { normalizeBaseUrl } from "./fsutil.js";
export { installUsagePlugins, resolveStatuslineCommand, } from "./usage-plugins.js";
export { USAGE_CLIENT_PKG, USAGE_OPENCODE_PKG } from "./constants.js";
import { adapters, getAdapter } from "./adapters/index.js";
/** Status of every known agent. */
export async function statusAll(opts) {
    return Promise.all(adapters.map((a) => a.status(opts)));
}
/** Apply InferHub settings to selected agents (default: all installed). */
export async function applyToAgents(agentIds, opts) {
    let targets = adapters;
    if (agentIds === "installed") {
        const statuses = await statusAll({ homeDir: opts.homeDir });
        const installed = new Set(statuses.filter((s) => s.installed).map((s) => s.id));
        targets = adapters.filter((a) => installed.has(a.id));
    }
    else if (agentIds !== "all") {
        targets = agentIds
            .map((id) => getAdapter(id))
            .filter((a) => !!a);
    }
    const results = [];
    for (const a of targets) {
        results.push(await a.apply(opts));
    }
    return results;
}
/** Reset InferHub settings on selected agents. */
export async function resetAgents(agentIds, opts) {
    const targets = agentIds === "all"
        ? adapters
        : agentIds
            .map((id) => getAdapter(id))
            .filter((a) => !!a);
    return Promise.all(targets.map((a) => a.reset(opts)));
}
